namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotalCommand(string CustomerTier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalCommand command) => command.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payableTotal = handler.Handle(new CalculatePayableTotalCommand("Gold", 100.00m));

        Assert.Equal(95.00m, payableTotal);
    }
}
E
